script:
(async()=>{
  const wait = ms => new Promise(r=>setTimeout(r,ms));
  const R = {};
  // 1. video detail expand
  const row = document.querySelector('#cohortList .vid-row');
  row.click(); await wait(300);
  R.detailOpen = !!document.querySelector('.vid-detail');
  R.detailAria = row.getAttribute('aria-expanded');
  R.detailLabels = [...document.querySelectorAll('.vid-detail .vd-label')].map(n=>n.textContent);
  R.detailHasWatchLink = !!document.querySelector('.vid-detail a[href*="youtube.com/watch"]');
  // collapse
  row.click(); await wait(250);
  R.detailClosed = !document.querySelector('.vid-detail');
  // 2. keyboard: g p -> packages
  document.dispatchEvent(new KeyboardEvent('keydown',{key:'g',bubbles:true}));
  document.dispatchEvent(new KeyboardEvent('keydown',{key:'p',bubbles:true}));
  await wait(400);
  R.viewAfterGP = document.querySelector('.view.is-active').dataset.view;
  R.hash = location.hash;
  // 3. tabs
  const tabs=[...document.querySelectorAll('#pkgTabs .tab')];
  R.tabCount = tabs.length;
  tabs[3].click(); await wait(350);
  R.selectedTab = document.querySelector('#pkgTabs .tab[aria-selected="true"]').dataset.tab;
  R.visiblePanels = [...document.querySelectorAll('[data-panel]')].filter(p=>!p.classList.contains('hidden')).map(p=>p.dataset.panel);
  const ind = document.querySelector('#tabIndicator');
  R.indicatorWidth = ind.style.width; R.indicatorX = ind.style.transform;
  // 4. shortcuts dialog
  document.dispatchEvent(new KeyboardEvent('keydown',{key:'?',bubbles:true}));
  await wait(250);
  R.dialogOpen = document.querySelector('#shortcuts').open;
  document.querySelector('#shortcutsClose').click(); await wait(200);
  R.dialogClosed = !document.querySelector('#shortcuts').open;
  // 5. theme toggle persists
  const before = getComputedStyle(document.body).backgroundColor;
  document.dispatchEvent(new KeyboardEvent('keydown',{key:'t',bubbles:true}));
  await wait(300);
  R.themeBefore = before;
  R.themeAfter = getComputedStyle(document.body).backgroundColor;
  R.themeStored = localStorage.getItem('vidpack-theme');
  R.themeIcon = document.querySelector('#themeIcon use').getAttribute('href');
  // 6. back to research + nav aria
  document.dispatchEvent(new KeyboardEvent('keydown',{key:'g',bubbles:true}));
  document.dispatchEvent(new KeyboardEvent('keydown',{key:'r',bubbles:true}));
  await wait(350);
  R.viewAfterGR = document.querySelector('.view.is-active').dataset.view;
  R.navCurrent = document.querySelector('.nav-item[aria-current="page"]').dataset.view;
  // 7. slash focuses omnibox
  document.dispatchEvent(new KeyboardEvent('keydown',{key:'/',bubbles:true}));
  await wait(150);
  R.focused = document.activeElement.id;
  window.__R = R;
})()
